package com.barlim1.starsprites;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class StarSpritePluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(
			StarSpritePlugin.class
		);

		RuneLite.main(args);
	}
}

package com.barlim1.starsprites;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Animation;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(
	name = "Star Sprites",
	description = "Restores Star Sprites after Shooting Stars are mined and tracks how many you rescue",
	tags = {"star", "sprite", "shooting star", "mining"}
)
public class StarSpritePlugin extends Plugin
{
	private static final int STAR_SPRITE_ID = 10632;
	private static final int STAR_SPRITE_IDLE_ANIMATION = 8864;
	private static final int RESCUE_SOUND_EFFECT = 4526;
	private static final int SPAWN_DISTANCE_TILES = 1;

	private static final String STAR_DESTROYED_MESSAGE =
		"The star disintegrates into dust.";

	private static final String STAR_SPRITE_NAME = "Star Sprite";

	private static final String CONFIG_GROUP = "starsprite";
	private static final String RESCUE_COUNT_KEY = "rescuedCount";
	private static final String RESET_PLUGIN_KEY = "resetPlugin";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	private RuneLiteObject starSprite;
	private int rescuedCount;

	@Provides
	StarSpriteConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(StarSpriteConfig.class);
	}

	@Override
	protected void startUp()
	{
		loadRescueCount();
	}

	@Override
	protected void shutDown()
	{
		clientThread.invoke(this::removeStarSprite);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState gameState = event.getGameState();

		/*
		 * Do not remove the sprite during GameState.LOADING.
		 * That could make it disappear immediately after spawning.
		 */
		if (gameState == GameState.LOGIN_SCREEN
			|| gameState == GameState.HOPPING
			|| gameState == GameState.CONNECTION_LOST)
		{
			removeStarSprite();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CONFIG_GROUP.equals(event.getGroup())
			&& RESET_PLUGIN_KEY.equals(event.getKey()))
		{
			resetPluginProgress();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE
			|| !STAR_DESTROYED_MESSAGE.equals(event.getMessage()))
		{
			return;
		}

		Player player = client.getLocalPlayer();

		if (player == null)
		{
			return;
		}

		spawnStarSprite(getTileInFrontOfPlayer(player));
	}

	private WorldPoint getTileInFrontOfPlayer(Player player)
	{
		WorldPoint playerLocation = player.getWorldLocation();
		int orientation = player.getOrientation() & 2047;

		int deltaX;
		int deltaY;

		if (orientation >= 1920 || orientation < 128)
		{
			deltaX = 0;
			deltaY = -1;
		}
		else if (orientation < 384)
		{
			deltaX = -1;
			deltaY = -1;
		}
		else if (orientation < 640)
		{
			deltaX = -1;
			deltaY = 0;
		}
		else if (orientation < 896)
		{
			deltaX = -1;
			deltaY = 1;
		}
		else if (orientation < 1152)
		{
			deltaX = 0;
			deltaY = 1;
		}
		else if (orientation < 1408)
		{
			deltaX = 1;
			deltaY = 1;
		}
		else if (orientation < 1664)
		{
			deltaX = 1;
			deltaY = 0;
		}
		else
		{
			deltaX = 1;
			deltaY = -1;
		}

		return new WorldPoint(
			playerLocation.getX() + deltaX * SPAWN_DISTANCE_TILES,
			playerLocation.getY() + deltaY * SPAWN_DISTANCE_TILES,
			playerLocation.getPlane()
		);
	}

	private void spawnStarSprite(WorldPoint worldLocation)
	{
		removeStarSprite();

		Player player = client.getLocalPlayer();

		if (worldLocation == null || player == null)
		{
			return;
		}

		LocalPoint spriteLocation = LocalPoint.fromWorld(
			client.getTopLevelWorldView(),
			worldLocation.getX(),
			worldLocation.getY()
		);

		if (spriteLocation == null)
		{
			return;
		}

		NPCComposition composition =
			client.getNpcDefinition(STAR_SPRITE_ID);

		if (composition == null)
		{
			return;
		}

		int[] modelIds = composition.getModels();

		if (modelIds == null || modelIds.length == 0)
		{
			return;
		}

		ModelData[] modelDataPieces =
			new ModelData[modelIds.length];

		short[] colorsToReplace =
			composition.getColorToReplace();

		short[] replacementColors =
			composition.getColorToReplaceWith();

		for (int i = 0; i < modelIds.length; i++)
		{
			ModelData modelData =
				client.loadModelData(modelIds[i]);

			if (modelData == null)
			{
				return;
			}

			if (colorsToReplace != null
				&& replacementColors != null)
			{
				modelData = modelData.cloneColors();

				int recolorCount = Math.min(
					colorsToReplace.length,
					replacementColors.length
				);

				for (int color = 0;
					color < recolorCount;
					color++)
				{
					modelData.recolor(
						colorsToReplace[color],
						replacementColors[color]
					);
				}
			}

			modelDataPieces[i] = modelData;
		}

		ModelData combinedModelData =
			modelDataPieces.length == 1
				? modelDataPieces[0]
				: client.mergeModels(modelDataPieces);

		if (combinedModelData == null)
		{
			return;
		}

		Model spriteModel = combinedModelData.light();

		Animation idleAnimation =
			client.loadAnimation(
				STAR_SPRITE_IDLE_ANIMATION
			);

		if (spriteModel == null
			|| idleAnimation == null)
		{
			return;
		}

		starSprite = client.createRuneLiteObject();

		starSprite.setModel(spriteModel);

		starSprite.setLocation(
			spriteLocation,
			worldLocation.getPlane()
		);

		starSprite.setOrientation(
			calculateOrientation(
				spriteLocation,
				player.getLocalLocation()
			)
		);

		starSprite.setAnimation(idleAnimation);

		starSprite
			.getAnimationController()
			.setOnFinished(
				controller -> controller.reset()
			);

		starSprite.setActive(true);

		recordRescue();
	}

	private void recordRescue()
	{
		rescuedCount++;

		saveRescueCount();

		client.playSoundEffect(RESCUE_SOUND_EFFECT);

		String rescueMessage;

		if (rescuedCount == 1)
		{
			rescueMessage =
				"You have rescued 1 Star Sprite.";
		}
		else
		{
			rescueMessage =
				"You have rescued "
					+ rescuedCount
					+ " Star Sprites.";
		}

		client.addChatMessage(
			ChatMessageType.GAMEMESSAGE,
			STAR_SPRITE_NAME,
			rescueMessage,
			null
		);
	}

	private int calculateOrientation(
		LocalPoint source,
		LocalPoint target)
	{
		int deltaX =
			target.getX() - source.getX();

		int deltaY =
			target.getY() - source.getY();

		int orientation = (int) (
			Math.atan2(deltaX, deltaY)
				* 325.94932345220167
		) & 2047;

		return (orientation + 1536) & 2047;
	}

	private void resetPluginProgress()
	{
		rescuedCount = 0;

		configManager.unsetConfiguration(
			CONFIG_GROUP,
			RESCUE_COUNT_KEY
		);

		if (client.getGameState()
			== GameState.LOGGED_IN)
		{
			client.addChatMessage(
				ChatMessageType.GAMEMESSAGE,
				STAR_SPRITE_NAME,
				"Star Sprite rescue count has been reset.",
				null
			);
		}
	}

	private void loadRescueCount()
	{
		String savedCount =
			configManager.getConfiguration(
				CONFIG_GROUP,
				RESCUE_COUNT_KEY
			);

		try
		{
			if (savedCount == null)
			{
				rescuedCount = 0;
			}
			else
			{
				rescuedCount = Math.max(
					0,
					Integer.parseInt(savedCount)
				);
			}
		}
		catch (NumberFormatException exception)
		{
			rescuedCount = 0;
		}
	}

	private void saveRescueCount()
	{
		configManager.setConfiguration(
			CONFIG_GROUP,
			RESCUE_COUNT_KEY,
			rescuedCount
		);
	}

	private void removeStarSprite()
	{
		if (starSprite != null)
		{
			starSprite.setActive(false);
			starSprite = null;
		}
	}
}

package com.barlim1.starsprites;

import java.awt.Button;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("starsprite")
public interface StarSpriteConfig extends Config
{
	@ConfigItem(
		keyName = "resetPlugin",
		name = "Reset rescue count",
		description = "Resets the number of Star Sprites you have rescued.",
		warning = "This permanently resets your Star Sprite rescue total."
	)
	default Button resetPlugin()
	{
		return new Button("Reset");
	}
}
